/* Device-local files, intentionally separate from localStorage metadata. */
window.SHFiles=(()=>{
 let dbPromise;
 const types=new Set(['image/jpeg','image/png','image/webp','application/pdf']);
 function database(){if(!globalThis.indexedDB)return Promise.reject(Error('This browser does not support local evidence storage.'));if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('shp-delivery-evidence',1);r.onupgradeneeded=()=>{const s=r.result.createObjectStore('files',{keyPath:'id'});s.createIndex('ownerId','ownerId');s.createIndex('projectId','projectId');};r.onsuccess=()=>{const db=r.result;db.onversionchange=()=>{db.close();dbPromise=null;};resolve(db);};r.onerror=()=>{dbPromise=null;reject(Error('Cannot open local evidence storage. Check browser storage permissions.'));};r.onblocked=()=>{dbPromise=null;reject(Error('Close other portal tabs before updating local evidence storage.'));};});return dbPromise;}
 async function operation(mode,fn){const db=await database();return new Promise((resolve,reject)=>{const tx=db.transaction('files',mode),s=tx.objectStore('files');let result;try{const req=fn(s);req.onsuccess=()=>{result=req.result};req.onerror=()=>reject(req.error||Error('Evidence operation failed'));tx.oncomplete=()=>resolve(result);tx.onabort=()=>reject(tx.error||Error('Evidence could not be saved; browser storage may be full.'));tx.onerror=()=>reject(tx.error||Error('Evidence could not be saved.'));}catch(e){tx.abort();reject(e);}});}
 function forProject(projectId){return {async put(record){if(record.projectId!==projectId||!record.ownerId||!record.id)throw Error('Evidence must belong to the active project and record.');if(!(record.blob instanceof Blob)||!types.has(record.type)||record.type!==record.blob.type||record.size!==record.blob.size)throw Error('Unsupported or inconsistent evidence file.');if(record.size<1||record.size>10*1024*1024)throw Error('Evidence must be non-empty and no larger than 10 MB.');const old=await operation('readonly',s=>s.get(record.id));if(old&&old.projectId!==projectId)throw Error('Evidence belongs to a different project.');await operation('readwrite',s=>s.put({...record,name:String(record.name||'evidence').replace(/[\\/]/g,'_').slice(0,180)}));return record.id;},async get(id){const r=await operation('readonly',s=>s.get(id));return r?.projectId===projectId?r:undefined;},async list(ownerId){const rows=await operation('readonly',s=>s.index('ownerId').getAll(ownerId));return rows.filter(x=>x.projectId===projectId);},async remove(id){const r=await operation('readonly',s=>s.get(id));if(r?.projectId===projectId)await operation('readwrite',s=>s.delete(id));}};}
 return {forProject};
})();
